from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, expiry_time]
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check if key exists
            if key in cache:
                val, expiry = cache[key]
                if t < expiry:
                    # still valid, just update
                    cache[key] = [value, t + ttl]
                    cache.move_to_end(key)
                    continue
                else:
                    # expired, remove it first
                    del cache[key]

            # key not present (or was expired and removed)
            if len(cache) >= capacity:
                cache.popitem(last=False)

            cache[key] = [value, t + ttl]
            cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                val, expiry = cache[key]
                if t < expiry:
                    results.append(val)
                    cache.move_to_end(key)
                else:
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

